CREATE OR REPLACE FUNCTION public.vi_period_data_dml()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO vi_period_data_base (period, period_end, period_kind, line_item, value, unit, yoy, assessment, summary, status, company_id, source_id) VALUES (NEW.period, NEW.period_end, NEW.period_kind, NEW.line_item, NEW.value, NEW.unit, NEW.yoy, NEW.assessment, NEW.summary, NEW.status, NEW.company_id, NEW.source_id) RETURNING id INTO NEW.id;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE vi_period_data_base SET period = NEW.period, period_end = NEW.period_end, period_kind = NEW.period_kind, line_item = NEW.line_item, value = NEW.value, unit = NEW.unit, yoy = NEW.yoy, assessment = NEW.assessment, summary = NEW.summary, status = NEW.status, company_id = NEW.company_id, source_id = NEW.source_id WHERE id = OLD.id;
    RETURN NEW;
  ELSE
    DELETE FROM vi_period_data_base WHERE id = OLD.id;
    RETURN OLD;
  END IF;
END $function$
